// Normalise input from either webhook or cron trigger
const isWebhook = $input.first().json.body !== undefined;

if (isWebhook) {
  const body = $input.first().json.body;
  return [
    {
      json: {
        type: body.type || 'webhook',
        content: body.content || '',
        sender: body.sender || 'unknown',
        metadata: body.metadata || {},
        source: 'webhook'
      }
    }
  ];
} else {
  // Cron trigger — inject daily task payload
  return [
    {
      json: {
        type: 'cron',
        content: 'Daily autonomous personnel review: run cold-contact scan, performance brief, and pipeline summary.',
        sender: 'system:cron',
        metadata: {
          tasks: ['cold_followups', 'performance_brief', 'pipeline_summary'],
          date: new Date().toISOString()
        },
        source: 'cron'
      }
    }
  ];
}

