const item = $input.first().json;

return [
  {
    json: {
      agent_name: item.agent || item.task_type || 'orchestrator',
      action: item.action_tier === 'auto_execute' ? 'agent_decision' : 'approval_requested',
      person_id: item.person_id || null,
      task_id: item.task_id || null,
      input_data: JSON.stringify({ task_type: item.task_type, sender: item.sender }),
      output_data: JSON.stringify({ decision: item.final_decision || item.action_tier, reasoning: item.reasoning }),
      reasoning: item.reasoning || '',
      action_tier: item.action_tier || 'auto_execute',
      confidence: item.confidence || null,
      success: true,
      created_at: new Date().toISOString()
    }
  }
];

// Build critical escalation notification for Legal/CHRO
const item = $input.first().json;

return [
  {
    json: {
      escalation_type: 'LEGAL_URGENT',
      priority: 'CRITICAL',
      subject: '[URGENT] Personnel Agent Critical Escalation — Immediate Review Required',
      body: `CRITICAL alert from Autonomous Personnel Agent.\n\nRisk Level: ${item.risk_level}\nReason: ${item.reason}\nKeywords: ${(item.keyword_flags || []).join(', ')}\nPolicy Flags: ${(item.policy_flags || []).join(', ')}\n\nOriginal content has been sanitised. Please review immediately.\n\nTimestamp: ${new Date().toISOString()}`,
      pii_flags: item.pii_found || [],
      keyword_flags: item.keyword_flags || [],
      policy_flags: item.policy_flags || [],
      task_id: item.task_id || null,
      timestamp: new Date().toISOString()
    }
  }
];

